import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

const MatchTone = 660;
const WinTone = 880;

function chime(frequency: number): void {
  const Context = window.AudioContext as typeof AudioContext | undefined;
  if (!Context) return;
  const audio = new Context();
  const tone = audio.createOscillator();
  const level = audio.createGain();
  tone.frequency.value = frequency;
  level.gain.value = 0.05;
  tone.connect(level).connect(audio.destination);
  tone.onended = () => void audio.close();
  tone.start();
  tone.stop(audio.currentTime + 0.12);
}

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    const matched = current.current.game.matched.length;
    commit(activateSession(current.current, index));
    if (current.current.game.matched.length > matched) chime(current.current.celebration ? WinTone : MatchTone);
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return { session, newGame, restart, loadBoard, loadSnapshot, exportSnapshot, activate, resume };
}
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { test } from 'vitest';
import { sourceFiles } from './source-files.ts';
import { isJsonObject } from '../src/game/saved-format.ts';

test('packages and lock use the reviewed exact versions and strict separate compiler projects', async () => {
  const pkg: unknown = JSON.parse(await readFile('package.json', 'utf8'));
  const expected: unknown = JSON.parse(
    await readFile(new URL('./package.fixture.json', import.meta.url), 'utf8'),
  );
  assert.ok(
    isJsonObject(pkg) &&
      isJsonObject(pkg.dependencies) &&
      isJsonObject(pkg.devDependencies) &&
      isJsonObject(expected),
  );
  const installed = { ...pkg.dependencies, ...pkg.devDependencies };
  assert.deepEqual(Object.keys(pkg.dependencies).sort(), ['react', 'react-dom']);
  for (const [name, version] of Object.entries(expected)) assert.equal(installed[name], version);
  const lock: unknown = JSON.parse(await readFile('package-lock.json', 'utf8'));
  assert.ok(isJsonObject(lock) && isJsonObject(lock.packages));
  const locked = lock.packages[''];
  assert.ok(isJsonObject(locked));
  assert.deepEqual(locked.dependencies, pkg.dependencies);
  assert.deepEqual(locked.devDependencies, pkg.devDependencies);
  assert.equal(pkg.type, 'module');
  const config: unknown = JSON.parse(await readFile('tsconfig.base.json', 'utf8'));
  assert.ok(isJsonObject(config) && isJsonObject(config.compilerOptions));
  for (const key of [
    'strict',
    'noUncheckedIndexedAccess',
    'exactOptionalPropertyTypes',
    'verbatimModuleSyntax',
    'erasableSyntaxOnly',
  ])
    assert.equal(config.compilerOptions[key], true);
  for (const project of ['app', 'node', 'e2e'])
    assert.ok(await readFile(`tsconfig.${project}.json`, 'utf8'));
  assert.ok(isJsonObject(pkg.scripts));
  assert.equal(
    pkg.scripts.typecheck,
    'tsc -p tsconfig.app.json && tsc -p tsconfig.node.json && tsc -p tsconfig.e2e.json',
    'T07 every compiler project',
  );
  assert.equal(pkg.scripts.test, 'vitest run', 'T02 Vitest runs unit tests');
});

test('authored TypeScript stays small, uses static ESM and rejects unsafe type escapes', async () => {
  const files = (await Promise.all(['src', 'scripts', 'tests', 'art'].map(sourceFiles))).flat();
  for (const file of files.filter((file) => /\.tsx?$/.test(file.path))) {
    assert.ok(file.text.trimEnd().split(/\r?\n/).length <= 200, file.path);
    assert.doesNotMatch(file.text, /@ts-(?:ignore|nocheck|expect-error)/);
    assert.doesNotMatch(
      file.text,
      /\bany\b|\bas\s+(?:[A-Z{]|unknown\b|number\b|string\b)|\bimport\s*\(|\brequire\s*\(/,
    );
  }
});

test('the game core has no browser effects and the shipped source has no audio or diagnostic entry', async () => {
  const files = await sourceFiles('src');
  const core = new Set(['deck.ts', 'game.ts', 'snapshot.ts', 'snapshot-selection.ts', 'replay.ts']);
  for (const file of files.filter((file) => !/\.(test|fixture)\./.test(file.path))) {
    assert.doesNotMatch(
      file.text,
      /AudioContext|new Audio\b|<audio|<canvas|fetch\(|XMLHttpRequest|window\.[a-zA-Z]*[Dd]eck/,
    );
    if (core.has(file.path.split(/[\\/]/).at(-1) ?? ''))
      assert.doesNotMatch(
        file.text,
        /\b(window|document|localStorage|performance|crypto|Date)\b|Math\.random/,
      );
    assert.doesNotMatch(file.text, /fixture|face-sheet|test-results/);
  }
});
import { expect, test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import {
  GAME_URL,
  exportedSnapshot,
  loadFixedBoard,
  loadTimedBoard,
  finishBoard,
} from './game-fixture.ts';

test('pauses elapsed time and a mismatch while the document is hidden', async ({ page }) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(200);
  // Headless Chromium leaves every tab visible, so control this browser input at the adapter.
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  const before = await exportedSnapshot(page);
  await page.clock.runFor(2000);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(before.elapsedMs);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => false });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(599);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
});

test('continues playing when access to browser storage is denied', async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', {
      get: () => {
        throw new DOMException('Blocked', 'SecurityError');
      },
    });
  });
  await loadFixedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await expect(page.locator('.card.matched')).toHaveCount(2);
});

test('keeps the initial focus and produces no audio during play', async ({ page }) => {
  let audioRequests = 0;
  page.on('request', (request) => {
    if (request.resourceType() === 'media') audioRequests += 1;
  });
  await page.goto(GAME_URL);
  expect(
    await page.locator('button:focus, select:focus, input:focus, textarea:focus').count(),
  ).toBe(0);
  await page.addInitScript(() => {
    for (const key of ['AudioContext', 'webkitAudioContext', 'Audio']) {
      Object.defineProperty(window, key, {
        configurable: true,
        value: class {
          constructor() {
            throw new Error('Unexpected synthesized audio');
          }
        },
      });
    }
    HTMLMediaElement.prototype.play = () => {
      throw new Error('Unexpected media playback');
    };
    speechSynthesis.speak = () => {
      throw new Error('Unexpected synthesized speech');
    };
  });
  await loadFixedBoard(page);
  await finishBoard(page);
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  await expect(page.locator('audio, video')).toHaveCount(0);
  expect(audioRequests).toBe(0);
});
